INSERT INTO "rewards" ("id", "brand_id", "category", "title", "description", "discount", "cost", "terms") VALUES
  ('20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'FOOD', 'Food delivery voucher', 'Take a break from cooking with a meal on us.', '₹150 off on orders above ₹499', 25, ARRAY['One use per account', 'Valid on selected restaurants']),
  ('20000000-0000-4000-8000-000000000005', '10000000-0000-4000-8000-000000000005', 'FOOD', 'Coffee break voucher', 'A small reward for a long week of hiring.', '₹200 off on orders above ₹700', 30, ARRAY['Valid at participating outlets', 'Cannot be combined with other offers']),
  ('20000000-0000-4000-8000-000000000006', '10000000-0000-4000-8000-000000000006', 'FOOD', 'Pizza night voucher', 'Make it a pizza night with the team.', '₹100 off on orders above ₹349', 15, ARRAY['One use per account', 'Valid on selected menu items']),
  ('20000000-0000-4000-8000-000000000007', '10000000-0000-4000-8000-000000000007', 'SHOPPING', 'Shopping voucher', 'Put your TalentCredits towards something useful.', '₹300 off on orders above ₹1,999', 60, ARRAY['Valid on selected products', 'Cannot be combined']),
  ('20000000-0000-4000-8000-000000000008', '10000000-0000-4000-8000-000000000008', 'SHOPPING', 'Shopping voucher', 'A little extra for your next online order.', '₹250 off on orders above ₹1,499', 50, ARRAY['Valid on selected products', 'Cannot be combined']),
  ('20000000-0000-4000-8000-000000000009', '10000000-0000-4000-8000-000000000009', 'SHOPPING', 'Wardrobe refresh voucher', 'Refresh your work wardrobe for less.', '₹400 off on orders above ₹1,999', 55, ARRAY['Valid on selected products', 'Cannot be combined']),
  ('20000000-0000-4000-8000-000000000010', '10000000-0000-4000-8000-000000000010', 'SHOPPING', 'Gear up voucher', 'Kit up for your next workout or weekend hike.', '₹300 off on orders above ₹1,500', 40, ARRAY['Valid on selected products', 'Cannot be combined']),
  ('20000000-0000-4000-8000-000000000011', '10000000-0000-4000-8000-000000000011', 'SHOPPING', 'Beauty haul voucher', 'Treat yourself to a little self-care.', '₹200 off on orders above ₹999', 35, ARRAY['Valid on selected products', 'Cannot be combined']),
  ('20000000-0000-4000-8000-000000000012', '10000000-0000-4000-8000-000000000012', 'TRAVEL', 'Ride credit', 'Get where you need to be for less.', '₹150 off your next 3 rides', 20, ARRAY['Valid on selected ride types', 'Expires 30 days after redemption']),
  ('20000000-0000-4000-8000-000000000013', '10000000-0000-4000-8000-000000000013', 'TRAVEL', 'Ride credit', 'A handy credit for your commute.', '₹120 off your next 2 rides', 18, ARRAY['Valid on selected ride types', 'Expires 30 days after redemption']),
  ('20000000-0000-4000-8000-000000000014', '10000000-0000-4000-8000-000000000014', 'TRAVEL', 'Stay voucher', 'Save on your next weekend away.', '₹1,000 off on stays above ₹8,000', 120, ARRAY['Valid on selected stays', 'Blackout dates may apply']),
  ('20000000-0000-4000-8000-000000000015', '10000000-0000-4000-8000-000000000015', 'ENTERTAINMENT', 'Movie night voucher', 'Catch the latest release on us.', '₹150 off on tickets above ₹500', 25, ARRAY['Valid on selected shows', 'Convenience fees excluded']),
  ('20000000-0000-4000-8000-000000000016', '10000000-0000-4000-8000-000000000016', 'ENTERTAINMENT', 'Premium voucher', 'Two months of ad-free listening.', '2 months of Premium on us', 35, ARRAY['New subscribers only', 'Auto-renews after the trial']),
  ('20000000-0000-4000-8000-000000000017', '10000000-0000-4000-8000-000000000017', 'ENTERTAINMENT', 'Gift card voucher', 'A gift card for your next binge.', '₹300 off a gift card purchase', 70, ARRAY['Valid on selected gift cards', 'One use per account']),
  ('20000000-0000-4000-8000-000000000018', '10000000-0000-4000-8000-000000000018', 'ENTERTAINMENT', 'Movie voucher', 'Bring a friend to the movies.', 'Buy 1 get 1 on select shows', 45, ARRAY['Valid on selected shows', 'Subject to seat availability'])
